'use strict';
/**
 * Client-side search over the pre-built search-index.json.
 * No build step needed at request time — the index is generated by
 * scripts/build.mjs and simply fetched here.
 */
(async () => {
  const input = document.getElementById('search-input');
  const grid = document.getElementById('post-grid');
  const meta = document.getElementById('search-meta');
  const noResults = document.getElementById('no-results');
  if (!input || !grid) return;

  const cards = Array.from(grid.querySelectorAll('.post-card'));

  let index = [];
  try {
    const res = await fetch('search-index.json');
    index = await res.json();
  } catch (err) {
    console.error('Could not load search index:', err);
    return;
  }

  // Map slug -> haystack (title + excerpt + tags + full text, lowercased)
  const haystacks = new Map(
    index.map((post) => [
      post.slug,
      [post.title, post.excerpt, (post.tags || []).join(' '), post.text || '']
        .join(' ')
        .toLowerCase(),
    ])
  );

  const params = new URLSearchParams(location.search);
  const initial = params.get('q') || '';
  if (initial) input.value = initial;

  function run(query) {
    const q = query.trim().toLowerCase();
    const terms = q.split(/\s+/).filter(Boolean);
    let visible = 0;

    for (const card of cards) {
      const slug = card.dataset.slug;
      const haystack = haystacks.get(slug) || '';
      const matches = terms.length === 0 || terms.every((t) => haystack.includes(t));
      card.hidden = !matches;
      if (matches) visible += 1;
    }

    noResults.hidden = visible !== 0;
    meta.textContent = q
      ? `${visible} post${visible === 1 ? '' : 's'} matching “${query.trim()}”`
      : `${cards.length} post${cards.length === 1 ? '' : 's'}`;

    const url = new URL(location.href);
    if (q) url.searchParams.set('q', query.trim());
    else url.searchParams.delete('q');
    history.replaceState(null, '', url);
  }

  input.addEventListener('input', (e) => run(e.target.value));
  run(initial);
})();
